var minOperations = function(nums) {
    let ans = 0;
    for (let i = 1; i < nums.length; ++i) {
        if (nums[i] <= nums[i - 1]) {
            const target = nums[i - 1] + 1;
            ans += target - nums[i];
            nums[i] = target;
        }
    }
    return ans;
};
